{
  "strengths": [
    "Exceptional memory for recalling factual information across subjects",
    "Strong academic proficiency in mathematics and science exceeding grade-level expectations",
    "Effective one-on-one communication skills with teachers and peers"
  ],
  "challenges": [
    "Difficulty navigating unstructured activities such as recess and lunch leading to social isolation",
    "Sensory over-responsivity to environmental noise causing distress",
    "Anxiety and behavioral dysregulation triggered by sudden, unannounced changes in daily routine"
  ],
  "learning_style": "Visual and structured learner who benefits from predictable routines, clear schedules, and task-oriented instructions due to Autism Spectrum Disorder.",
  "recommended_supports": [
    "Visual schedules and advance warnings for any transitions or changes in classroom routine",
    "Noise-canceling headphones or a designated quiet work corner to manage auditory sensitivity",
    "Structured, facilitated peer activities or interest-based lunch clubs to support social engagement"
  ],
  "short_term_goals": [
    "By end of Term 1, student will independently transition between classroom activities using a visual schedule without emotional outbursts as measured by teacher observation logs over 3 consecutive weeks.",
    "By end of Term 2, student will participate in one structured, adult-facilitated peer cooperative activity during recess twice a week as measured by playground observation checklists."
  ],
  "long_term_goals": [
    "By end of academic year, student will successfully initiate conversation and maintain a two-turn reciprocal interaction with a peer during unstructured periods in at least 4 out of 5 recorded opportunities, as measured by weekly counselor and teacher tracking sheets."
  ],
  "academic_performance": {
    "overall_level": "above_grade",
    "strong_subjects": [
      "Mathematics",
      "Science"
    ],
    "weak_subjects": [
      "Social Studies"
    ],
    "grade_trajectory": "stable"
  },
  "behavioural_notes": [
    "Performs exceptionally well when tasks are structured and predictable.",
    "Experiences distress and behavioral rigidity during unexpected schedule modifications."
  ],
  "assistive_tech_needs": [
    "Noise-canceling headphones for auditory sensory regulation"
  ]
}
